import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA kernel for 3D matmul: A (N, M, K), B (K, L) -> C (N, M, L)
# ----------------------------------------------------------------------
matmul_kernel_cuda = '''
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N, int M, int K, int L) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * M * L) {
        int n = idx / (M * L);
        int tmp = idx % (M * L);
        int m = tmp / L;
        int l = tmp % L;
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[(n * M + m) * K + k] * B[k * L + l];
        }
        C[idx] = sum;
    }
}
'''

# C++ wrapper that allocates output and launches the kernel
matmul_cuda_cpp_source = '''
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    const int N = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    const int L = B.size(1);

    const int BLOCK_SIZE = 256;
    const int NUM_BLOCKS = (N * M * L + BLOCK_SIZE - 1) / BLOCK_SIZE;

    auto out = torch::empty({N, M, L}, device=A.device());
    out.set_requires_grad_(false);

    matmul_kernel<<<NUM_BLOCKS, BLOCK_SIZE>>>(
        reinterpret_cast<const float*>(A.data_ptr()),
        reinterpret_cast<const float*>(B.data_ptr()),
        reinterpret_cast<float*>(out.data_ptr()),
        N, M, K, L
    );

    return out;
}
'''

# Load the compiled inline CUDA function
matmul = load_inline(
    name="matmul_cuda",
    cpp_sources="",
    cuda_sources=matmul_cuda_cpp_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.matmul_cuda = matmul

    def forward(self, A, B):
        """
        Args:
            A: Input 3D tensor of shape (N, M, K).
            B: Input matrix of shape (K, L).
        Returns:
            Output tensor of shape (N, M, L) = A @ B (matrix multiplication along the last dimension of A).
        """
        return self.matmul_cuda(A, B)
